    {'code': '736005', 'port_slug': 'hong-kong', 'title': 'Pre-Dinner Harbor Cruise', 'slug': 'pre-dinner-harbor-cruise-736005', 'price': 89.99, 'price_unit': 'Person', 'rating': None, 'review_count': 0, 'desc_html': None, 'image_url': 'https://www.carnival.com/shop/medias/736005-img1.jpg?context=bWFzdGVyfGltYWdlc3wzMDU1NDl8aW1hZ2UvanBlZ3xhR1E0TDJnM1pTODVOVGd3TnpRM05EZzVNekV3THpjek5qQXdOUzFwYldjeExtcHdad3xkYjIzY2Y2YzZkYzFjYWFhMDc2NDE4NGJlM2U0YWZmN2FkNTJjZTNlNTcyODI1YTA2ZTgwZTIxZTQyZjZhNzgw', 'duration': '', 'activity_level': '', 'min_age': ''},
    {'code': '736003', 'port_slug': 'hong-kong', 'title': 'Lantau by Skyrail', 'slug': 'lantau-by-skyrail-736003', 'price': 94.99, 'price_unit': 'Person', 'rating': None, 'review_count': 0, 'desc_html': '<strong>Lantau:</strong> Board the Ngong Ping 360 for a stunning four-mile cable car ride to the majestic Big Buddha on Lantau Island, where visitors can experience its grandeur and spiritual significance. Enjoy the panoramic views and explore the adjacent themed village for a captivating cultural experience.\n', 'image_url': '/shop/medias/736003-img1.jpg?context=bWFzdGVyfGltYWdlc3wzMDc2MTh8aW1hZ2UvanBlZ3xhREppTDJoaVppODVOVFEzTURFeE9UUTROVGMwTHpjek5qQXdNeTFwYldjeExtcHdad3xjN2RjNjk5ZWE1ZTRkODdjOTA4ZDM2NDhlMzU4NTJmYjgzNWE4MjAxZjRmMWIyMGNkYTE4YzRhNzlkN2JlZGQw', 'duration': '', 'activity_level': '', 'min_age': ''},
