    {'code': '168032', 'port_slug': 'ketchikan-ward-cove', 'title': 'Alaskan Bear Encounter by Land & Sea', 'slug': 'alaskan-bear-encounter-by-land--sea-168032', 'price': 514.99, 'price_unit': 'Adult', 'rating': None, 'review_count': 0, 'desc_html': None, 'image_url': 'https://www.carnival.com/shop/medias/170097-img1.jpg?context=bWFzdGVyfGltYWdlc3wzMDY3ODl8aW1hZ2UvanBlZ3xhR000TDJnek5pODRPVGN5TkRneE1UWTNNemt3THpFM01EQTVOeTFwYldjeExtcHdad3w1MDg3ZjFlNjAwN2ZhNDcyYWI5NzE1Y2Y1N2M1YTBlM2Q2MDA4NjgzMWZjYWJlZmFlMTRhZDI4MjFjN2I5Y2Uy&w=1232&h=647&resize_profile=pdphero', 'duration': '', 'activity_level': '', 'min_age': ''},
    {'code': '168008', 'port_slug': 'ketchikan-ward-cove', 'title': 'Wilderness Adventure & Crab Feast', 'slug': 'wilderness-adventure--crab-feast-168008', 'price': 237.99, 'price_unit': 'Adult', 'rating': 5.0, 'review_count': 1, 'desc_html': '<p><strong>Scenic Views:</strong> After a scenic 45-minute transfer, board a heated vessel for a 7-mile coastal cruise past George Inlet Cannery, learning about traditional fish traps from your knowledgeable guides.<br />\n<br />\n<strong>Crab Fishery:</strong> Cross the fjords to explore a secluded estuary known for the Dungeness Crab Fishery, as guides demonstrate crab pot pulls and share insights on crab biology. Participate in resetting the pots before traveling to George Inlet Lodge.<br />\n<br />\n<strong>George Inlet Lodge:</strong> Visit the George Inlet Lodge, a converted cannery bunkhouse on stilts above the fjords. Enjoy a steaming hot Dungeness Crab feast, unlimited beverages (soda, wine, and beer).<br />\n<br />\n<strong>What’s Included:</strong></p>\n<ul>\n\t<li>Dungeness Crab feast with unlimited soda, wine, and beer.</li>\n</ul>\n', 'image_url': '/shop/medias/y01-02-Miss-Patricia-and-Cannery.jpg?context=bWFzdGVyfGltYWdlc3wyMjY2Njl8aW1hZ2UvanBlZ3xhVzFoWjJWekwyZ3dPUzlvTmprdk9EZ3hOREU0TkRRek1UWTBOaTVxY0djfDBlMjNlYWI4MjkzYjUzMjRkYzAwY2MxZjQxZDQ2OGE5YWViYTM2NDQ2N2JhYjVlMDNhMTEwYmY1ZGU3ZWJhZDI', 'duration': '', 'activity_level': '', 'min_age': ''},
