    {'code': '829024', 'port_slug': 'ponta-delgada', 'title': 'Sete Cidades Highlights', 'slug': 'sete-cidades-highlights-829024', 'price': 104.99, 'price_unit': 'Person', 'rating': 1.0, 'review_count': 1, 'desc_html': None, 'image_url': 'https://www.carnival.com/shop/medias/y01-New2-Sete-Cidades-Highlights-with-2-stops-Sete-Cidades-Lakes.jpg?context=bWFzdGVyfGltYWdlc3wxODQ0ODV8aW1hZ2UvanBlZ3xhVzFoWjJWekwyZ3dNaTlvTVRndk9EZ3hORE15TWpnME16WTNPQzVxY0djfDdiODEyZWM0NjEyZDkwMjk3OTdmNTQyZTQzYWFjZDkxNTdhNDg3N2ZhNGM5NGRmOWVmMzEyZjc2MWU2ZWQxM2Q', 'duration': '', 'activity_level': '', 'min_age': ''},
    {'code': '829027', 'port_slug': 'ponta-delgada', 'title': 'Whale & Dolphin Watching Catamaran', 'slug': 'whale--dolphin-watching-catamaran-829027', 'price': 154.99, 'price_unit': 'Adult', 'rating': None, 'review_count': 0, 'desc_html': None, 'image_url': 'https://www.carnival.com/shop/medias/829027-img1.jpg?context=bWFzdGVyfGltYWdlc3wzMTU5Njd8aW1hZ2UvanBlZ3xhR1UxTDJoaU9DODVNREkyTVRZNE1Ua3pNRFUwTHpneU9UQXlOeTFwYldjeExtcHdad3w0NGNlZDBhNDYzZGZiZWU3NGIzZjEwYjI1NjVlNDhlYmE1ZTlhMzc0YmE1ZTQ5MGMwZTU2ZDY0MzYxOWRjZjBi', 'duration': '', 'activity_level': '', 'min_age': ''},
    {'code': '829029', 'port_slug': 'ponta-delgada', 'title': 'Ponta Delgada Foody Tour', 'slug': 'ponta-delgada-foody-tour-829029', 'price': 179.99, 'price_unit': 'Person', 'rating': None, 'review_count': 0, 'desc_html': "<p><strong>Downtown Exploration:</strong> Wander through the charming streets of Ponta Delgada, discovering hidden alleys and bustling eateries.<br />\n<br />\n<strong>Progressive Menu:</strong> Indulge in a progressive menu featuring a tantalizing array of local delicacies, from fresh fruits and honey to savory seafood and meats, culminating in an artisanal dessert.<br />\n<br />\n<strong>Tea Tasting:</strong> Sample delicious local teas at a traditional tea house, experiencing the unique flavors of Azorean blends.<br />\n<br />\n<strong>Farmers Market:</strong> Explore the vibrant Farmers Market, where Mediterranean, African, and American ingredients mingle with Asian spices, creating a sensory feast.<br />\n<br />\n<strong>Cultural Insights:</strong> Gain insight into the city's history and culture as you visit landmarks and hear fascinating stories from your knowledgeable guide.<br />\n<br />\n<strong>What’s Included:</strong></p>\n<ul>\n\t<li>Food and beverage tastings.</li>\n</ul>\n", 'image_url': '/shop/medias/829029-img1.jpg?context=bWFzdGVyfGltYWdlc3wzMTU4MDN8aW1hZ2UvanBlZ3xhRGM0TDJnME55ODVNREkyTVRjd05UVXlNelV3THpneU9UQXlPUzFwYldjeExtcHdad3xkZGY0ZjcxOGVhMTU0YzhmMzhjYWIwMzlmMDBmYThmZWFiN2NmMDViZDU2ODg1MTNiOTc4NmJkMjZjMWI0ZDQy', 'duration': '', 'activity_level': '', 'min_age': ''},
