    {'code': '863001', 'port_slug': 'st-peter-port', 'title': 'Guernsey Wildlife RIB Adventure', 'slug': 'guernsey-wildlife-rib-adventure-863001', 'price': 159.99, 'price_unit': 'Person', 'rating': None, 'review_count': 0, 'desc_html': None, 'image_url': 'https://www.carnival.com/shop/medias/863001-img1.jpg?context=bWFzdGVyfGltYWdlc3wzMTY4NTV8aW1hZ2UvanBlZ3xhRGsyTDJnME55ODVOVEE0T1RFek5qUXpOVFV3THpnMk16QXdNUzFwYldjeExtcHdad3wzMmZmZWIyN2Q5NzYwMWJmOWVlYTU1NjZjNWE3Nzc4ZmRhZDc4MjJlODQyYjBlNTY2NTYzY2Q2MWUyY2ViMzE3', 'duration': '', 'activity_level': '', 'min_age': ''},
    {'code': '863002', 'port_slug': 'st-peter-port', 'title': 'Coast and Countryside drive', 'slug': 'coast-and-countryside-drive-863002', 'price': 179.99, 'price_unit': 'Person', 'rating': None, 'review_count': 0, 'desc_html': "<p><strong>Island Views:</strong> Experience the beauty of Guernsey on a scenic drive that showcases dramatic cliffs, golden bays, and picturesque countryside. Take in the views of St. Peter Port, with its historic harbor, 11th-century Town Church, and Castle Cornet. Visit the enchanting Little Chapel, adorned with seashells and colorful china, then stop at Pleinmont Cliffs for breathtaking sea vistas and perfect photo opportunities. Along the way, discover the island's unique WWII history through remnants of coastal fortifications.<br />\n<br />\n<strong>Local Delights:</strong> Stop for a delightful treat of tea or coffee and Guernsey gâche, with time to shop for souvenirs.<br />\n<br />\n<strong>What’s Included:</strong></p>\n<ul>\n\t<li>Tea or coffee with traditional Guernsey gâche (local cake).</li>\n</ul>\n", 'image_url': '/shop/medias/863002-img1.jpg?context=bWFzdGVyfGltYWdlc3wzMTg3NDN8aW1hZ2UvanBlZ3xhRFUzTDJneU1pODVOVEE0T1RFME5qVTVNelU0THpnMk16QXdNaTFwYldjeExtcHdad3w2M2JjOThkMmIwOTVlMTgxODJkOTRmZTIyMTYxOWYxMzNmMDIzZmYyNDI5OWMwYWY3OTBjMmQ0MTk2ZmJhNTNk', 'duration': '', 'activity_level': '', 'min_age': ''},
